#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>
#include <string.h>

// Helper function for error checking
void check_error(int err, const char *msg) {
    if (err != 0) {
        fprintf(stderr, "Error: %s failed: %s\n", msg, strerror(err));
        // Cleanup is omitted for simplicity, but mandatory in production code
        exit(EXIT_FAILURE);
    }
}

void* thread_func(void *arg) {
    // Thread executes using explicit scheduling parameters defined in attributes
    printf("Worker thread created with explicit scheduling attributes.\n");
    return NULL;
}

int main() {
    pthread_attr_t attr;
    pthread_t thread_id;
    int inherit_mode;
    int ret;

    // 1. Initialize the attributes object
    ret = pthread_attr_init(&attr);
    check_error(ret, "pthread_attr_init");

    // 2. Set the attribute to EXPLICIT scheduling
    // If this fails, the system might not support changing scheduling parameters.
    ret = pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
    check_error(ret, "pthread_attr_setinheritsched");

    // 3. Verify the setting
    ret = pthread_attr_getinheritsched(&attr, &inherit_mode);
    check_error(ret, "pthread_attr_getinheritsched");

    if (inherit_mode == PTHREAD_EXPLICIT_SCHED) {
        printf("Inherit mode successfully set to PTHREAD_EXPLICIT_SCHED.\n");
    } else {
        fprintf(stderr, "Failed to set explicit scheduling mode.\n");
        pthread_attr_destroy(&attr);
        exit(EXIT_FAILURE);
    }

    // Note: For PTHREAD_EXPLICIT_SCHED to be effective, we would usually also call
    // pthread_attr_setschedpolicy() and pthread_attr_setschedparam() here.

    // 4. Create the thread
    ret = pthread_create(&thread_id, &attr, thread_func, NULL);
    check_error(ret, "pthread_create");

    // 5. Cleanup and join
    pthread_join(thread_id, NULL);
    pthread_attr_destroy(&attr);

    printf("Program finished.\n");
    return 0;
}
